function primeSubOperation(nums) {
  const limit = 1000;
  const isPrime = new Array(limit + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;
  for (let p = 2; p * p <= limit; p++) {
    if (isPrime[p]) {
      for (let multiple = p * p; multiple <= limit; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }
  const primes = [];
  for (let p = 2; p <= limit; p++) {
    if (isPrime[p]) {
      primes.push(p);
    }
  }

  let prev = 0;
  for (const num of nums) {
    let low = 0;
    let high = primes.length - 1;
    let pick = 0;
    while (low <= high) {
      const mid = (low + high) >> 1;
      if (primes[mid] < num - prev) {
        pick = primes[mid];
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    const value = num - pick;
    if (value <= prev) {
      return false;
    }
    prev = value;
  }
  return true;
}

