function primeSubOperation(nums) {
  const prime = (x) => {
    if (x < 2) return false;
    for (let d = 2; d < x; d++) if (x % d === 0) return false;
    return true;
  };
  // reachable holds every value the previous element can end with on some valid path.
  let reachable = new Set([0]);
  for (const num of nums) {
    const options = [num];
    for (let p = 2; p < num; p++) if (prime(p)) options.push(num - p);
    const next = new Set();
    for (const v of options) for (const u of reachable) if (u < v) { next.add(v); break; }
    if (next.size === 0) return false;
    reachable = next;
  }
  return true;
}

