function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const primes = [];
  for (let x = 2; x <= 1000; x++) {
    let ok = true;
    for (let d = 2; d * d <= x; d++) if (x % d === 0) { ok = false; break; }
    if (ok) primes.push(x);
  }
  if (size === 'small') {
    const n = int(1, 7);
    const top = rand() < 0.7 ? 25 : 1000;
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = int(300, 1000);
  const mode = rand();
  if (mode < 0.25) return [Array.from({ length: n }, () => int(1, 1000))];
  // Build a strictly increasing target and hide each value behind a random prime.
  const pool = Array.from({ length: 1000 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const target = pool.slice(0, n).sort((a, b) => a - b);
  const nums = target.map(b => {
    const room = primes.filter(p => b + p <= 1000);
    return room.length && rand() < 0.6 ? b + room[Math.floor(rand() * room.length)] : b;
  });
  if (mode < 0.6) {
    const i = int(1, n - 1);
    nums[i] = int(1, Math.max(1, nums[i - 1]));
  }
  return [nums];
}
